SELECT id, dateDiff('year', d, toDate('2025-01-01')), dateDiff('month', dt, toDateTime('2025-01-01 00:00:00')), dateDiff('week', d, toDate('2024-06-01')), dateDiff('day', dny, toDateTime('2024-06-01 00:00:00', 'America/New_York')), dateDiff('hour', dtz, toDateTime('2024-06-01 00:00:00')), dateDiff('minute', dt, dt64), dateDiff('second', dt64, dt64u), dateDiff('ms', dt64, dt64u) FROM t30 ORDER BY id
